import java.util.List;
import java.util.Map;
import java.util.Set;

public class ClaimOffice {

    private static final int PROCESSING_FEE_IN_G = 5;

    private static final Map<String, Integer> MAIN_ITEM_BASE_PREMIUM_PRICE_LIST_IN_G = Map.of(
            "sword", 100,
            "amulet", 60,
            "staff", 80,
            "potion", 40);

    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");

    private static final int COMPONENT_BASE_PREMIUM_IN_G = 25;

    private final Customer customer;

    public ClaimOffice(Customer customer) {
        this.customer = customer;
    }

    public int basePremium(List<Item> items) {
        return items.stream()
                .mapToInt(this::basePremiumOf)
                .sum();
    }

    private int basePremiumOf(Item item) {
        if (isComponent(item)) {
            return COMPONENT_BASE_PREMIUM_IN_G;
        }
        return MAIN_ITEM_BASE_PREMIUM_PRICE_LIST_IN_G.get(item.type());
    }

    private boolean isComponent(Item item) {
        return COMPONENT_TYPES.contains(item.type());
    }

    public int quote(List<Item> items) {
        return PROCESSING_FEE_IN_G;
    }
}
