/**
 * The MHPCO's policy-wide premium modifiers. Unlike the item-specific risk
 * surcharges, these are measured against the policy premium as a whole and
 * depend on the customer's history with the MHPCO rather than on any item.
 *
 * This is the one place that says which modifiers are policy-wide: the initial
 * assessment surcharge and the follow-up contract discount are added here and
 * nowhere else.
 */
public final class PolicyWideModifiers {

    private static final int LOYALTY_YEARS = 2;

    private static final int LOYALTY_DISCOUNT_PERCENT = 20;

    private final Customer customer;

    public PolicyWideModifiers(Customer customer) {
        this.customer = customer;
    }

    /**
     * The net effect of every policy-wide modifier on a policy premium:
     * positive amounts are charged to the customer, negative amounts are
     * granted to the customer.
     */
    public int totalPolicyModifiers(int policyPremium) {
        return -loyaltyDiscount(policyPremium);
    }

    /**
     * Long-standing customers -- 2 or more years of business with the MHPCO --
     * receive a 20 % loyalty discount on the policy premium.
     */
    private int loyaltyDiscount(int policyPremium) {
        if (customer.yearsWithMHPCO() < LOYALTY_YEARS) {
            return 0;
        }
        return policyPremium * LOYALTY_DISCOUNT_PERCENT / 100;
    }
}
import java.util.List;

public class ClaimOffice {

    private static final int PROCESSING_FEE_IN_G = 5;

    private final PolicyWideModifiers policyWideModifiers;

    public ClaimOffice(Customer customer) {
        this.policyWideModifiers = new PolicyWideModifiers(customer);
    }

    /**
     * The policy base premium is the sum of the base premiums of the main items
     * and of the components, each priced by its own MHPCO pricing policy.
     */
    public int basePremium(List<Item> items) {
        return MainItemPricing.mainItemsBasePremium(items)
                + ComponentPricing.componentsBasePremium(items);
    }

    /**
     * Item-specific modifiers apply to the base premium of the affected item,
     * not to the policy total.
     */
    public int premiumAfterItemModifiers(List<Item> items) {
        return basePremium(items) + ItemRiskSurcharges.totalItemSurcharges(items);
    }

    /**
     * The MHPCO assembles a premium in a fixed order: the policy base premium,
     * then the item-specific risk surcharges, then the policy-wide modifiers,
     * and the processing fee at the very end.
     */
    public int quote(List<Item> items) {
        int premium = premiumAfterItemModifiers(items);
        return premium
                + policyWideModifiers.totalPolicyModifiers(premium)
                + PROCESSING_FEE_IN_G;
    }
}
