import java.util.List;
import java.util.Optional;

/**
 * The items one issued policy covers, as the office reads them when settling
 * an incident: which covered item a reported damage was suffered by, and the
 * refusal when none is.
 *
 * These are one decision. The matching rule says which covered item answers to
 * a reported damage -- by type today, by an item the damage names outright
 * tomorrow, and one insured item per reported damage once the office starts
 * counting them -- and the refusal is that rule's other outcome, not a rule
 * beside it: the office declines the whole claim rather than settling the rest
 * of the incident around a damage it covers no item for. It refuses a damage
 * naming an item type the office does not insure at all on the same ground and
 * in the same words, because such a policy covers no such item either; the
 * MHPCO's price list is not consulted at claim time.
 *
 * What the covered items are insured for is a separate decision, made by
 * {@link InsuranceValues}: the office may revalue what it covers without
 * changing how it matches a damage to an item.
 *
 * Not to be confused with {@link InsurableItems}, which decides what the
 * office will take on at all; this says what one issued policy already covers.
 */
public final class CoveredItems implements Coverage {

    private final List<Item> insuredItems;

    public CoveredItems(List<Item> insuredItems) {
        this.insuredItems = List.copyOf(insuredItems);
    }

    /**
     * The insured item the reported damage was suffered by, or the office's
     * refusal of the whole claim when this policy covers no such item.
     */
    @Override
    public Item damagedIn(Damage damage) {
        return matching(damage).orElseThrow(() -> notCovered(damage));
    }

    /**
     * Which covered item answers to a reported damage: the first one of the
     * damaged type.
     */
    private Optional<Item> matching(Damage damage) {
        return insuredItems.stream()
                .filter(item -> item.type().equals(damage.itemType()))
                .findFirst();
    }

    /**
     * The office declines a damage it covers no item for.
     */
    private static IllegalArgumentException notCovered(Damage damage) {
        return new IllegalArgumentException(
                "This policy does not cover an item of type " + damage.itemType());
    }
}
/**
 * What a policy covers, as a reimbursement needs to see it: which insured
 * item a reported damage was suffered by.
 *
 * Reimbursing a damage depends on the item that suffered it -- its
 * enchantment, its material -- but not on how that item is found among the
 * ones a policy covers. This is the name of that dependency, so the office's
 * reimbursement clauses and a policy's record of what it covers change for
 * their own reasons. {@link CoveredItems} is how an issued policy answers
 * it.
 */
@FunctionalInterface
public interface Coverage {

    /**
     * The insured item the reported damage was suffered by.
     */
    Item damagedIn(Damage damage);
}
import java.util.List;

/**
 * A policy the MHPCO has issued over a list of insured items: what the office
 * covers, and what the covered items are insured for.
 *
 * Each of those is a decision the policy holds together rather than makes.
 * What the covered items are worth is {@link InsuranceValues}; how far beyond
 * that sum the office will pay out, and what claims leave of it, is
 * {@link PayoutCap}; which covered item a reported damage was suffered by is
 * {@link CoveredItems}.
 */
public final class Policy {

    private final CoveredItems coveredItems;

    private final int insuranceSumInG;

    private final PayoutCap payoutCap;

    public Policy(List<Item> insuredItems) {
        this.coveredItems = new CoveredItems(insuredItems);
        this.insuranceSumInG = InsuranceValues.insuranceSumOf(insuredItems);
        this.payoutCap = PayoutCap.overInsuranceSum(insuranceSumInG);
    }

    /**
     * What the covered items are insured for, all together.
     */
    public int insuranceSum() {
        return insuranceSumInG;
    }

    /**
     * The most the MHPCO will pay out over the life of this policy, as it was
     * set when the policy was issued. Claims settled since have not moved it;
     * what they have left of it is {@link Claim#remainingCap()}.
     */
    public int cap() {
        return payoutCap.total();
    }

    /**
     * The MHPCO settles an incident against this policy: it reimburses the
     * incident as far as the policy's cap still reaches, and reports what the
     * settlement leaves of that cap.
     */
    public Claim claim(Incident incident) {
        int payout = payoutCap.drawDown(Reimbursement.forIncident(incident, coveredItems));
        return new Claim(payout, payoutCap.remaining());
    }
}

